// Regenerate `test/spec-conformance/generated.ts` from the Iceberg REST
// OpenAPI spec. The generated file is imported by `types.test.ts` to verify
// our handwritten types are structurally compatible with the spec's schemas.
//
// Spec is fetched fresh from upstream at the tag in `spec-pin.json`. See
// `scripts/spec-source.mjs` for env-var overrides.

import { writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import yaml from 'js-yaml'
import openapiTS, { astToString } from 'openapi-typescript'
import { loadSpecYaml, ICEBERG_REST_SPEC_TAG } from './spec-source.mjs'

const __dirname = dirname(fileURLToPath(import.meta.url))
const OUT = resolve(__dirname, '../test/spec-conformance/generated.ts')

const raw = await loadSpecYaml()
const parsed = yaml.load(raw)

const ast = await openapiTS(parsed, {
  // Don't promote fields with `default: ...` to required. The spec relies on
  // explicit `required: [...]` lists, so honor those instead of the default
  // heuristic (which would force callers to specify fields the spec marks optional).
  defaultNonNullable: false,
})
const banner = `// AUTOGENERATED by scripts/gen-spec-types.mjs from apache/iceberg@${ICEBERG_REST_SPEC_TAG}.\n// Do not edit.\n\n`
await writeFile(OUT, banner + astToString(ast), 'utf-8')

console.log(`Wrote ${OUT}`)
